import { describe, expect, it, vi } from "vitest";
import { createTerminalDefaultColorQueryResponder } from "../src/browser.js";

const DARK_COLORS = { foreground: "#d7dae0", background: "#0e1015", cursor: "#ff5c5c" };
const LIGHT_COLORS = { foreground: "#1b1e26", background: "#f7f8fa", cursor: "#1b1e26" };

describe("terminal default-color query responder", () => {
  it("answers OSC 10 and 11 queries with Ghostty-compatible RGB values", () => {
    const reply = vi.fn();
    const responder = createTerminalDefaultColorQueryResponder({
      getColors: () => DARK_COLORS,
      reply,
    });

    responder.observe("prefix\u001b]10;?\u001b\\\u001b]11;?\u0007suffix");

    expect(reply.mock.calls.map(([data]) => data)).toEqual([
      "\u001b]10;rgb:d7d7/dada/e0e0\u001b\\",
      "\u001b]11;rgb:0e0e/1010/1515\u0007",
    ]);
  });

  it("answers successive slots and preserves the request terminator", () => {
    const reply = vi.fn();
    const responder = createTerminalDefaultColorQueryResponder({
      getColors: () => DARK_COLORS,
      reply,
    });

    responder.observe("\u001b]10;?;?;?\u0007");

    expect(reply.mock.calls.map(([data]) => data)).toEqual([
      "\u001b]10;rgb:d7d7/dada/e0e0\u0007",
      "\u001b]11;rgb:0e0e/1010/1515\u0007",
      "\u001b]12;rgb:ffff/5c5c/5c5c\u0007",
    ]);
  });

  it("recognizes each query across every stream split", () => {
    for (const query of ["\u001b]10;?\u0007", "\u001b]11;?\u001b\\"]) {
      for (let split = 1; split < query.length; split += 1) {
        const reply = vi.fn();
        const responder = createTerminalDefaultColorQueryResponder({
          getColors: () => DARK_COLORS,
          reply,
        });

        responder.observe(query.slice(0, split));
        expect(reply).not.toHaveBeenCalled();
        responder.observe(query.slice(split));

        expect(reply).toHaveBeenCalledOnce();
      }
    }
  });

  it("uses current colors when the terminal theme changes", () => {
    let colors = DARK_COLORS;
    const reply = vi.fn();
    const responder = createTerminalDefaultColorQueryResponder({
      getColors: () => colors,
      reply,
    });

    responder.observe("\u001b]11;?\u001b\\");
    colors = LIGHT_COLORS;
    responder.observe("\u001b]11;?\u001b\\");

    expect(reply.mock.calls.map(([data]) => data)).toEqual([
      "\u001b]11;rgb:0e0e/1010/1515\u001b\\",
      "\u001b]11;rgb:f7f7/f8f8/fafa\u001b\\",
    ]);
  });

  it("advances past setters while replying to later query slots", () => {
    const reply = vi.fn();
    const responder = createTerminalDefaultColorQueryResponder({
      getColors: () => DARK_COLORS,
      reply,
    });

    responder.observe("\u001b]10;#ffffff;?\u001b\\");

    expect(reply).toHaveBeenCalledWith("\u001b]11;rgb:0e0e/1010/1515\u001b\\");
  });

  it("advances past empty fields while replying to later query slots", () => {
    const reply = vi.fn();
    const responder = createTerminalDefaultColorQueryResponder({
      getColors: () => DARK_COLORS,
      reply,
    });

    responder.observe("\u001b]10;;?\u0007");

    expect(reply).toHaveBeenCalledWith("\u001b]11;rgb:0e0e/1010/1515\u0007");
  });

  it("queues replies before invoking a synchronous reentrant callback", () => {
    const replies: string[] = [];
    let responder: ReturnType<typeof createTerminalDefaultColorQueryResponder>;
    responder = createTerminalDefaultColorQueryResponder({
      getColors: () => DARK_COLORS,
      reply: (data) => {
        replies.push(data);
        if (replies.length === 1) {
          responder.observe("\u001b]12;?\u0007");
        }
      },
    });

    responder.observe("\u001b]10;?;?\u0007");

    expect(replies).toEqual([
      "\u001b]10;rgb:d7d7/dada/e0e0\u0007",
      "\u001b]11;rgb:0e0e/1010/1515\u0007",
      "\u001b]12;rgb:ffff/5c5c/5c5c\u0007",
    ]);
  });

  it("restarts at a new OSC after an unterminated query", () => {
    const reply = vi.fn();
    const responder = createTerminalDefaultColorQueryResponder({
      getColors: () => DARK_COLORS,
      reply,
    });

    responder.observe("\u001b]11;junk\u001b]10;?\u0007");

    expect(reply).toHaveBeenCalledOnce();
    expect(reply).toHaveBeenCalledWith("\u001b]10;rgb:d7d7/dada/e0e0\u0007");
  });

  it("recovers from canceled color queries", () => {
    const reply = vi.fn();
    const responder = createTerminalDefaultColorQueryResponder({
      getColors: () => DARK_COLORS,
      reply,
    });

    responder.observe("\u001b]11;junk\u0018\u001b]10;?\u0007");

    expect(reply).toHaveBeenCalledOnce();
    expect(reply).toHaveBeenCalledWith("\u001b]10;rgb:d7d7/dada/e0e0\u0007");
  });

  it("ignores unrelated commands and invalid color values", () => {
    const reply = vi.fn();
    const responder = createTerminalDefaultColorQueryResponder({
      getColors: () => ({ ...DARK_COLORS, background: "transparent" }),
      reply,
    });

    responder.observe("\u001b]13;?\u001b\\\u001b]11;?\u001b\\");

    expect(reply).not.toHaveBeenCalled();
  });

  it("suppresses replay replies while retaining a trailing query prefix", () => {
    const reply = vi.fn();
    const responder = createTerminalDefaultColorQueryResponder({
      getColors: () => DARK_COLORS,
      reply,
    });

    responder.primeFromReplay("\u001b]10;?\u001b\\history\u001b]11;");
    expect(reply).not.toHaveBeenCalled();
    responder.observe("?\u001b\\");

    expect(reply).toHaveBeenCalledOnce();
    expect(reply).toHaveBeenCalledWith("\u001b]11;rgb:0e0e/1010/1515\u001b\\");
  });

  it("recovers after an oversized unterminated color sequence", () => {
    const reply = vi.fn();
    const responder = createTerminalDefaultColorQueryResponder({
      getColors: () => DARK_COLORS,
      reply,
    });

    responder.observe(`\u001b]10;${"x".repeat(1025)}`);
    responder.observe("\u001b]11;?\u0007");

    expect(reply).toHaveBeenCalledOnce();
    expect(reply).toHaveBeenCalledWith("\u001b]11;rgb:0e0e/1010/1515\u0007");
  });
});

import { setImmediate } from "node:timers/promises";
import { describe, expect, it, vi } from "vitest";
import {
  TerminalHubClient,
  attachTerminalStream,
  createGhosttyTerminal,
  type TerminalHubWebSocket,
} from "../src/browser.js";
import { TerminalMessageType, decodeTerminalFrame, encodeTerminalFrame } from "../src/protocol.js";

describe("createGhosttyTerminal", () => {
  it.each(["resize", "fit", "ready"])("rejects cancellation during %s startup", async (phase) => {
    const abort = new AbortController();
    const reason = new Error("cancelled during startup");
    const dispose = vi.fn();
    const statuses: string[] = [];
    class Terminal extends TestGhosttyTerminal {
      resize(): void {
        abort.abort(reason);
      }
      dispose = dispose;
    }
    class FitAddon extends TestGhosttyFitAddon {
      fit(): void {
        if (phase === "fit") {
          abort.abort(reason);
        }
      }
    }
    await expect(
      createGhosttyTerminal({
        parent: {} as HTMLElement,
        runtime: { ghostty: {}, Terminal, FitAddon } as never,
        size: phase === "resize" ? { columns: 40, rows: 10 } : undefined,
        signal: abort.signal,
        onStatus: ({ state }) => {
          statuses.push(state);
          if (phase === "ready" && state === "ready") {
            abort.abort(reason);
          }
        },
      }),
    ).rejects.toBe(reason);
    expect(dispose).toHaveBeenCalledOnce();
    expect(statuses).toEqual(phase === "ready" ? ["loading", "ready"] : ["loading"]);
  });

  it("preserves abort reasons raised while Ghostty is loading", async () => {
    const controller = new AbortController();
    const reason = new Error("cancelled by caller");
    let finishLoad: ((value: unknown) => void) | undefined;
    const loaded = new Promise((resolve) => {
      finishLoad = resolve;
    });
    const module = {
      Ghostty: { load: () => loaded },
    } as unknown as typeof import("ghostty-web");

    const created = createGhosttyTerminal({
      parent: {} as HTMLElement,
      runtimeOptions: { module },
      signal: controller.signal,
    });
    controller.abort(reason);
    finishLoad?.({});

    await expect(created).rejects.toBe(reason);
  });

  it("preserves an explicit null abort reason during startup", async () => {
    const abort = new AbortController();
    const dispose = vi.fn();
    class Terminal extends TestGhosttyTerminal {
      dispose = dispose;
    }
    await expect(
      createGhosttyTerminal({
        parent: {} as HTMLElement,
        runtime: { ghostty: {}, Terminal, FitAddon: TestGhosttyFitAddon } as never,
        signal: abort.signal,
        onStatus: ({ state }) => {
          if (state === "ready") {
            abort.abort(null);
          }
        },
      }),
    ).rejects.toBeNull();
    expect(dispose).toHaveBeenCalledOnce();
  });

  it("removes the caller abort listener when the terminal is disposed", async () => {
    const listeners = new Set<() => void>();
    const signal = {
      aborted: false,
      addEventListener: (_type: string, listener: () => void) => listeners.add(listener),
      removeEventListener: (_type: string, listener: () => void) => listeners.delete(listener),
    } as unknown as AbortSignal;
    const controller = await createGhosttyTerminal({
      parent: {} as HTMLElement,
      signal,
      runtime: {
        ghostty: {},
        Terminal: TestGhosttyTerminal,
        FitAddon: TestGhosttyFitAddon,
      } as never,
    });

    expect(listeners.size).toBe(1);
    controller.dispose();
    expect(listeners.size).toBe(0);
  });
});

describe("attachTerminalStream", () => {
  it("keeps the browser export identical to the renderer-neutral stream export", async () => {
    const stream = await import("../src/stream.js");
    expect(attachTerminalStream).toBe(stream.attachTerminalStream);
  });
  it.each([
    ["read", "sync"],
    ["read", "async"],
    ["write", "sync"],
    ["write", "async"],
  ])("preserves a %s failure when %s iterator cleanup fails", async (operation, cleanup) => {
    const failure = new Error(`${operation} failed`);
    const cleanupFailure = new Error("cleanup failed");
    const returned = vi.fn(() => {
      if (cleanup === "sync") {
        throw cleanupFailure;
      }
      return Promise.reject(cleanupFailure);
    });
    const source = {
      [Symbol.asyncIterator]: () => ({
        next: async () => {
          if (operation === "read") {
            throw failure;
          }
          return { done: false as const, value: new Uint8Array([1]) };
        },
        return: returned,
      }),
    };
    await expect(
      attachTerminalStream(
        {
          write: () => {
            throw failure;
          },
        },
        source,
      ),
    ).rejects.toBe(failure);
    expect(returned).toHaveBeenCalledOnce();
  });

  it.each([
    ["before attachment", "sync"],
    ["before attachment", "async"],
    ["while reading", "sync"],
    ["while reading", "async"],
  ])("suppresses %s abort cleanup errors from a %s return", async (when, cleanup) => {
    const controller = new AbortController();
    const returned = vi.fn(() => {
      const failure = new Error("cleanup failed");
      if (cleanup === "sync") {
        throw failure;
      }
      return Promise.reject(failure);
    });
    if (when === "before attachment") {
      controller.abort();
    }
    const source = {
      [Symbol.asyncIterator]: () => ({
        next: () => new Promise<IteratorResult<Uint8Array>>(() => undefined),
        return: returned,
      }),
    };
    const attached = attachTerminalStream({ write: vi.fn() }, source, controller.signal);
    controller.abort();
    await expect(attached).resolves.toBeUndefined();
    expect(returned).toHaveBeenCalledOnce();
  });

  it("stops waiting for cleanup on abort while retaining the original failure", async () => {
    const controller = new AbortController();
    const failure = new Error("write failed");
    let rejectCleanup!: (reason: unknown) => void;
    const cleanup = new Promise<IteratorResult<Uint8Array>>((_, reject) => {
      rejectCleanup = reject;
    });
    const returned = vi.fn(() => cleanup);
    const rejected = vi.fn();
    const attached = attachTerminalStream(
      {
        write: () => {
          throw failure;
        },
      },
      {
        [Symbol.asyncIterator]: () => ({
          next: async () => ({ done: false as const, value: new Uint8Array([1]) }),
          return: returned,
        }),
      },
      controller.signal,
    ).catch(rejected);
    try {
      await vi.waitFor(() => expect(returned).toHaveBeenCalledOnce());
      controller.abort();
      await vi.waitFor(() => expect(rejected).toHaveBeenCalledWith(failure));
    } finally {
      rejectCleanup(new Error("late cleanup failure"));
      await attached;
    }
  });

  it.each(["before attachment", "while a read resolves"])(
    "does not write buffered output aborted %s",
    async (when) => {
      const controller = new AbortController();
      const queued = [new Uint8Array([1]), new Uint8Array([2])];
      const returned = vi.fn(async () => ({ done: true as const, value: undefined }));
      const source = {
        [Symbol.asyncIterator]: () => ({
          next: async () =>
            queued.length
              ? { done: false as const, value: queued.shift()! }
              : { done: true as const, value: undefined },
          return: returned,
        }),
      };
      const write = vi.fn();
      if (when === "before attachment") {
        controller.abort();
      }
      const attached = attachTerminalStream({ write }, source, controller.signal);
      controller.abort();
      await attached;
      expect(write).not.toHaveBeenCalled();
      expect(returned).toHaveBeenCalledOnce();
    },
  );

  it("does not read another chunk after a write callback aborts", async () => {
    const controller = new AbortController();
    const queued = [new Uint8Array([1]), new Uint8Array([2])];
    const next = vi.fn(async () =>
      queued.length
        ? { done: false as const, value: queued.shift()! }
        : { done: true as const, value: undefined },
    );
    const returned = vi.fn(async () => ({ done: true as const, value: undefined }));
    const write = vi.fn(() => controller.abort());
    await attachTerminalStream(
      { write },
      { [Symbol.asyncIterator]: () => ({ next, return: returned }) },
      controller.signal,
    );
    expect(write).toHaveBeenCalledOnce();
    expect(next).toHaveBeenCalledOnce();
    expect(returned).toHaveBeenCalledOnce();
  });

  it("writes terminal byte chunks in order", async () => {
    const writes: string[] = [];
    await attachTerminalStream(
      {
        write: (chunk: string | Uint8Array) => {
          writes.push(typeof chunk === "string" ? chunk : new TextDecoder().decode(chunk));
        },
      },
      chunks("one", "two"),
    );
    expect(writes).toEqual(["one", "two"]);
  });

  it("stops waiting when aborted", async () => {
    const controller = new AbortController();
    const attached = attachTerminalStream({ write: () => undefined }, never(), controller.signal);
    controller.abort();
    await expect(attached).resolves.toBeUndefined();
  });

  it("closes the source iterator when terminal writes fail", async () => {
    let returned = false;
    const source = {
      [Symbol.asyncIterator]: () => ({
        next: async () => ({ done: false as const, value: new Uint8Array([1]) }),
        return: async () => {
          returned = true;
          return { done: true as const, value: undefined };
        },
      }),
    };
    await expect(
      attachTerminalStream(
        {
          write: () => {
            throw new Error("terminal disposed");
          },
        },
        source,
      ),
    ).rejects.toThrow("terminal disposed");
    expect(returned).toBe(true);
  });
});

describe("TerminalHubClient", () => {
  it("drops an asynchronous frame converted after caller close", async () => {
    const socket = new TestTerminalHubSocket();
    vi.spyOn(socket, "close").mockImplementation(() => {
      socket.readyState = 2;
    });
    const onFrame = vi.fn();
    const client = new TerminalHubClient({
      url: "ws://terminal.test",
      socketFactory: () => socket,
      onFrame,
    });
    client.connect();
    socket.open();
    let finish!: (value: ArrayBuffer) => void;
    const pending = new Promise<ArrayBuffer>((resolve) => {
      finish = resolve;
    });
    socket.receive({ arrayBuffer: () => pending });
    await setImmediate();
    client.close();
    finish(ownedArrayBuffer(encodeTerminalFrame({ type: TerminalMessageType.Output })));
    await setImmediate();
    expect(onFrame).not.toHaveBeenCalled();
    socket.emitClose();
  });

  it.each(["Buffer", "ArrayBuffer", "DataView"])(
    "captures %s bytes before queuing frame delivery",
    async (kind) => {
      const socket = new TestTerminalHubSocket();
      const frames: string[] = [];
      const client = new TerminalHubClient({
        url: "wss://terminal.example",
        socketFactory: () => socket,
        onFrame: (frame) => frames.push(new TextDecoder().decode(frame.payload)),
      });
      client.connect();
      socket.open();
      const source = Buffer.from(
        encodeTerminalFrame({
          type: TerminalMessageType.Output,
          payload: new TextEncoder().encode("safe"),
        }),
      );
      const buffer = ownedArrayBuffer(source);
      socket.receive(
        kind === "Buffer" ? source : kind === "ArrayBuffer" ? buffer : new DataView(buffer),
      );
      source.fill(0);
      new Uint8Array(buffer).fill(0);

      await vi.waitFor(() => expect(frames).toEqual(["safe"]));
      client.close();
    },
  );

  it.each(["Buffer", "ArrayBuffer", "arrayBuffer method"])(
    "owns normalized %s frames from injected transports",
    async (kind) => {
      const socket = new TestTerminalHubSocket();
      const frames: Uint8Array[] = [];
      const client = new TerminalHubClient({
        url: "wss://terminal.example",
        socketFactory: () => socket,
        onFrame: (frame) => frames.push(frame.payload),
      });
      client.connect();
      socket.open();
      const buffer = new Uint8Array(
        encodeTerminalFrame({
          type: TerminalMessageType.Output,
          payload: new TextEncoder().encode("safe"),
        }),
      ).buffer;
      const source = kind === "Buffer" ? Buffer.from(buffer) : new Uint8Array(buffer);
      socket.receive(
        kind === "Buffer"
          ? source
          : kind === "ArrayBuffer"
            ? buffer
            : { arrayBuffer: async () => buffer },
      );
      await vi.waitFor(() => expect(frames).toHaveLength(1));
      source.fill(120);
      expect(new TextDecoder().decode(frames[0])).toBe("safe");
      client.close();
    },
  );

  it("handles conversion failures while an earlier frame is still queued", async () => {
    const socket = new TestTerminalHubSocket();
    const events: unknown[] = [];
    let resolveFirst!: (bytes: ArrayBuffer) => void;
    const first = new Promise<ArrayBuffer>((resolve) => {
      resolveFirst = resolve;
    });
    const failure = new Error("conversion failed");
    const client = new TerminalHubClient({
      url: "wss://terminal.example",
      socketFactory: () => socket,
      onFrame: () => events.push("frame"),
      onError: (error) => events.push(error),
    });
    client.connect();
    socket.open();
    socket.receive({ arrayBuffer: () => first });
    socket.receive({
      arrayBuffer: async () => {
        throw failure;
      },
    });
    await setImmediate();
    expect(events).toEqual([]);
    resolveFirst(ownedArrayBuffer(encodeTerminalFrame({ type: TerminalMessageType.Output })));
    await vi.waitFor(() => expect(events).toEqual(["frame", failure]));
    client.close();
  });

  it("sends the protocol hello and delivers decoded frames in order", async () => {
    const socket = new TestTerminalHubSocket();
    const frames: Array<{ sessionId: string; payload: string }> = [];
    const client = new TerminalHubClient({
      url: "wss://terminal.example",
      socketFactory: () => socket,
      onFrame: (frame) => {
        frames.push({
          sessionId: frame.sessionId,
          payload: new TextDecoder().decode(frame.payload),
        });
      },
    });

    client.connect();
    socket.open();
    expect(decodeTerminalFrame(socket.sent[0] as Uint8Array)).toMatchObject({
      type: TerminalMessageType.Hello,
      sessionId: "",
    });

    socket.receive(
      new Blob([
        ownedArrayBuffer(
          encodeTerminalFrame({
            type: TerminalMessageType.Output,
            sessionId: "IS-1",
            payload: new TextEncoder().encode("first"),
          }),
        ),
      ]),
    );
    socket.receive(
      encodeTerminalFrame({
        type: TerminalMessageType.Output,
        sessionId: "IS-2",
        payload: new TextEncoder().encode("second"),
      }),
    );

    await vi.waitFor(() => expect(frames).toHaveLength(2));
    expect(frames).toEqual([
      { sessionId: "IS-1", payload: "first" },
      { sessionId: "IS-2", payload: "second" },
    ]);
  });

  it("uses caller-supplied frame limits when sending", () => {
    const socket = new TestTerminalHubSocket();
    const client = new TerminalHubClient({
      url: "wss://terminal.example",
      frameLimits: { maxFrameBytes: 2 * 1024 * 1024 },
      socketFactory: () => socket,
    });

    client.connect();
    socket.open();
    expect(
      client.send({
        type: TerminalMessageType.Output,
        sessionId: "IS-1",
        payload: new Uint8Array(1024 * 1024),
      }),
    ).toBe(true);
  });

  it("reconnects only while the application still needs the transport", async () => {
    vi.useFakeTimers();
    const sockets: TestTerminalHubSocket[] = [];
    const client = new TerminalHubClient({
      url: "wss://terminal.example",
      reconnectDelayMs: 10,
      shouldReconnect: () => true,
      socketFactory: () => {
        const socket = new TestTerminalHubSocket();
        sockets.push(socket);
        return socket;
      },
    });

    try {
      client.connect();
      sockets[0].open();
      sockets[0].emitClose();
      await vi.advanceTimersByTimeAsync(9);
      expect(sockets).toHaveLength(1);
      await vi.advanceTimersByTimeAsync(1);
      expect(sockets).toHaveLength(2);

      sockets[1].open();
      sockets[1].emitClose();
      expect(vi.getTimerCount()).toBe(1);
      client.close();
      expect(vi.getTimerCount()).toBe(0);
      await vi.advanceTimersByTimeAsync(10);
      expect(sockets).toHaveLength(2);
    } finally {
      client.close();
      vi.useRealTimers();
    }
  });

  it.each(["unused", "throws", "closes"])(
    "rechecks reconnect eligibility when the delayed predicate %s",
    async (mode) => {
      vi.useFakeTimers();
      const sockets: TestTerminalHubSocket[] = [];
      const error = new Error("reconnect predicate failed");
      const onError = vi.fn();
      let delayed = false;
      const client = new TerminalHubClient({
        url: "wss://terminal.example",
        reconnectDelayMs: 10,
        shouldReconnect: () => {
          if (!delayed) {
            return true;
          }
          if (mode === "throws") {
            throw error;
          }
          if (mode === "closes") {
            client.close();
            return true;
          }
          return false;
        },
        onError,
        socketFactory: () => {
          const socket = new TestTerminalHubSocket();
          sockets.push(socket);
          return socket;
        },
      });
      try {
        client.connect();
        sockets[0].open();
        sockets[0].emitClose();
        expect(vi.getTimerCount()).toBe(1);
        delayed = true;

        await vi.advanceTimersByTimeAsync(10);

        expect(sockets).toHaveLength(1);
        expect(vi.getTimerCount()).toBe(0);
        if (mode === "throws") {
          expect(onError).toHaveBeenCalledWith(error);
        }
      } finally {
        client.close();
        vi.useRealTimers();
      }
    },
  );

  it("does not let a stalled prior socket block frames after reconnecting", async () => {
    const sockets: TestTerminalHubSocket[] = [];
    const frames: string[] = [];
    let resolveOldPayload: (value: ArrayBuffer) => void = noop;
    const oldPayload = new Promise<ArrayBuffer>((resolve) => {
      resolveOldPayload = resolve;
    });
    const client = new TerminalHubClient({
      url: "wss://terminal.example",
      reconnectDelayMs: 1,
      shouldReconnect: () => true,
      socketFactory: () => {
        const socket = new TestTerminalHubSocket();
        sockets.push(socket);
        return socket;
      },
      onFrame: (frame) => frames.push(new TextDecoder().decode(frame.payload)),
    });

    client.connect();
    sockets[0]?.open();
    sockets[0]?.receive({ arrayBuffer: () => oldPayload });
    await Promise.resolve();
    sockets[0]?.emitClose();
    await vi.waitFor(() => expect(sockets).toHaveLength(2));
    sockets[1]?.open();
    sockets[1]?.receive(
      encodeTerminalFrame({
        type: TerminalMessageType.Output,
        sessionId: "IS-2",
        payload: new TextEncoder().encode("new"),
      }),
    );

    await vi.waitFor(() => expect(frames).toEqual(["new"]));
    resolveOldPayload(
      ownedArrayBuffer(
        encodeTerminalFrame({
          type: TerminalMessageType.Output,
          sessionId: "IS-1",
          payload: new TextEncoder().encode("old"),
        }),
      ),
    );
    await setImmediate();
    expect(frames).toEqual(["new"]);
    client.close();
  });

  it.each([1001, 1011, 4001])("preserves code %i when an injected transport accepts it", (code) => {
    const socket = new TestTerminalHubSocket();
    const close = vi.spyOn(socket, "close");
    const client = new TerminalHubClient({
      url: "wss://terminal.example",
      socketFactory: () => socket,
    });
    client.connect();
    socket.open();

    client.close(code, "done");

    expect(close.mock.calls).toEqual([[code, "done"]]);
    expect(socket.readyState).toBe(3);
  });

  it.each([1011.5, 4001.5])(
    "normalizes fractional close code %f before calling the transport",
    (code) => {
      const socket = new TestTerminalHubSocket();
      const close = vi.spyOn(socket, "close");
      const client = new TerminalHubClient({
        url: "wss://terminal.example",
        socketFactory: () => socket,
      });
      client.connect();
      socket.open();

      client.close(code, "done");

      expect(close.mock.calls).toEqual([[1000, "done"]]);
      expect(socket.readyState).toBe(3);
    },
  );

  it("retries without arguments when both coded close attempts fail", () => {
    const socket = new TestTerminalHubSocket();
    const close = vi
      .spyOn(socket, "close")
      .mockImplementationOnce(() => {
        throw new Error("first attempt");
      })
      .mockImplementationOnce(() => {
        throw new Error("second attempt");
      });
    const client = new TerminalHubClient({
      url: "wss://terminal.example",
      socketFactory: () => socket,
    });
    client.connect();
    socket.open();

    client.close();

    expect(close.mock.calls).toEqual([
      [1000, "terminal hub closed"],
      [1000, "terminal hub closed"],
      [],
    ]);
    expect(socket.readyState).toBe(3);
  });

  it("reports a failed teardown and retains the socket for retry", () => {
    const socket = new TestTerminalHubSocket();
    const failure = new Error("close unavailable");
    const errors: unknown[] = [];
    const close = vi.spyOn(socket, "close").mockImplementation(() => {
      throw failure;
    });
    const client = new TerminalHubClient({
      url: "wss://terminal.example",
      socketFactory: () => socket,
      onError: (error) => errors.push(error),
    });
    client.connect();
    socket.open();

    client.close();

    expect(close).toHaveBeenCalledTimes(3);
    expect(errors).toEqual([failure]);
    expect(client.isOpen).toBe(true);
    close.mockRestore();
    client.close();
    expect(socket.readyState).toBe(3);
    expect(client.isOpen).toBe(false);
  });
});

async function* chunks(...values: string[]): AsyncIterable<Uint8Array> {
  for (const value of values) {
    yield new TextEncoder().encode(value);
  }
}

function never(): AsyncIterable<Uint8Array> {
  return {
    [Symbol.asyncIterator]: () => ({
      next: () => new Promise<IteratorResult<Uint8Array>>(() => undefined),
    }),
  };
}

type TestTerminalHubListeners = {
  open: () => void;
  message: (event: { data: unknown }) => void;
  close: (event: { code?: number; reason?: string }) => void;
  error: () => void;
};

class TestTerminalHubSocket implements TerminalHubWebSocket {
  readyState = 0;
  binaryType?: string;
  readonly sent: Array<string | ArrayBuffer | ArrayBufferView | Blob> = [];
  private readonly listeners: {
    [Type in keyof TestTerminalHubListeners]: Set<TestTerminalHubListeners[Type]>;
  } = { open: new Set(), message: new Set(), close: new Set(), error: new Set() };

  send(data: string | ArrayBuffer | ArrayBufferView | Blob): void {
    this.sent.push(data);
  }

  close(code?: number, reason?: string): void {
    this.emitClose(code, reason);
  }

  addEventListener<Type extends keyof TestTerminalHubListeners>(
    type: Type,
    listener: TestTerminalHubListeners[Type],
  ): void {
    this.listeners[type].add(listener);
  }

  removeEventListener<Type extends keyof TestTerminalHubListeners>(
    type: Type,
    listener: TestTerminalHubListeners[Type],
  ): void {
    this.listeners[type].delete(listener);
  }

  open(): void {
    this.readyState = 1;
    for (const listener of this.listeners.open) {
      listener();
    }
  }

  receive(data: unknown): void {
    for (const listener of this.listeners.message) {
      listener({ data });
    }
  }

  emitClose(code = 1000, reason = ""): void {
    this.readyState = 3;
    for (const listener of this.listeners.close) {
      listener({ code, reason });
    }
  }
}

class TestGhosttyTerminal {
  readonly options: { disableStdin?: boolean };

  constructor(options: { disableStdin?: boolean }) {
    this.options = options;
  }

  loadAddon(): void {}

  open(): void {}

  onData(): { dispose(): void } {
    return { dispose: () => undefined };
  }

  onResize(): { dispose(): void } {
    return { dispose: () => undefined };
  }

  resize(): void {}

  write(): void {}

  dispose(): void {}
}

class TestGhosttyFitAddon {
  fit(): void {}

  observeResize(): void {}

  dispose(): void {}
}

function ownedArrayBuffer(bytes: Uint8Array): ArrayBuffer {
  const copied = new Uint8Array(bytes.byteLength);
  copied.set(bytes);
  return copied.buffer;
}

function noop(): void {}
import { Buffer } from "node:buffer";

import { readFile, stat, writeFile } from "node:fs/promises";
import { expect, test } from "@playwright/test";
import type { GhosttyTerminalController } from "../../src/browser.js";
import type { TerminalSize } from "../../src/index.js";

declare global {
  interface Window {
    smokeTerminal: GhosttyTerminalController;
    smokeInput: string[];
    smokeResizes: TerminalSize[];
    smokeStartupMs: number;
    smokeRuntimeMs: number;
  }
}

for (const assets of ["node", "worker"]) {
  test(`${assets} assets dispose a terminal cancelled during startup`, async ({ page }) => {
    await page.goto(`/?assets=${assets}`);
    await expect(page.locator("body")).toHaveAttribute("data-ready", "true");
    const result = await page.evaluate(async (assetSource) => {
      const moduleUrl = "/dist/browser.js";
      const browser = (await import(moduleUrl)) as typeof import("../../src/browser.js");
      const prefix = assetSource === "worker" ? "/worker" : "";
      const runtime = await browser.loadGhosttyRuntime({
        wasmUrl: `${prefix}/vendor/ghostty-vt.wasm`,
      });
      const parent = document.createElement("div");
      document.body.append(parent);
      const abort = new AbortController();
      const statuses: string[] = [];
      let rejected = false;
      try {
        const terminal = await browser.createGhosttyTerminal({
          parent,
          runtime,
          size: { columns: 40, rows: 10 },
          signal: abort.signal,
          onResize: () => abort.abort("cancelled during resize"),
          onStatus: ({ state }) => statuses.push(state),
        });
        terminal.dispose();
      } catch (error) {
        rejected = error === "cancelled during resize";
      }
      return { rejected, statuses, canvases: parent.querySelectorAll("canvas").length };
    }, assets);
    expect(result).toEqual({ rejected: true, statuses: ["loading"], canvases: 0 });
  });

  test(`${assets} assets preserve input, resize, fit, and disposal`, async ({ page }) => {
    const wasm = page.waitForResponse((response) => response.url().endsWith("ghostty-vt.wasm"));
    await page.goto(`/?assets=${assets}`);
    await expect(page.locator("body")).toHaveAttribute("data-ready", "true");
    expect((await wasm).headers()["x-smoke-asset-source"]).toBe(assets);

    await page.evaluate(() => window.smokeTerminal.terminal.focus());
    await page.keyboard.type("ignored");
    expect(await page.evaluate(() => window.smokeInput)).toEqual([]);
    await page.evaluate(() => window.smokeTerminal.setReadOnly(false));
    await page.keyboard.type("input-ok");
    await page.keyboard.press("Enter");
    await expect.poll(() => page.evaluate(() => window.smokeInput.join(""))).toBe("input-ok\r");
    await page.evaluate(() => window.smokeTerminal.setReadOnly(true));
    await page.keyboard.type("ignored-again");
    expect(await page.evaluate(() => window.smokeInput.join(""))).toBe("input-ok\r");

    expect(
      await page.evaluate(() => {
        window.smokeTerminal.resize({ columns: 60, rows: 12 });
        return [window.smokeTerminal.terminal.cols, window.smokeTerminal.terminal.rows];
      }),
    ).toEqual([60, 12]);
    expect(await page.evaluate(() => window.smokeResizes.at(-1))).toEqual({
      columns: 60,
      rows: 12,
    });
    expect(
      await page.evaluate(() => {
        const parent = document.querySelector<HTMLElement>("#terminal")!;
        parent.style.width = "400px";
        parent.style.height = "160px";
        window.smokeTerminal.fit();
        const { cols, rows } = window.smokeTerminal.terminal;
        return cols > 0 && cols < 60 && rows > 0 && rows < 12;
      }),
    ).toBe(true);

    expect(
      await page.evaluate(() => {
        window.smokeTerminal.dispose();
        window.smokeTerminal.dispose();
        try {
          window.smokeTerminal.write(new Uint8Array([65]));
        } catch (error) {
          return (error as { code: string }).code;
        }
        return null;
      }),
    ).toBe("transport_closed");
    await expect(page.locator("#terminal canvas")).toHaveCount(0);
  });

  for (const workload of ["plain", "unicode", "escapes"] as const) {
    test(`${assets} assets sustain ${workload} output and record a baseline`, async ({
      page,
      browser,
    }, testInfo) => {
      test.setTimeout(180_000);
      const errors: string[] = [];
      page.on("pageerror", (error) => errors.push(error.message));
      await page.goto(`/?assets=${assets}`);
      await expect(page.locator("body")).toHaveAttribute("data-ready", "true");
      const measurements = await page.evaluate(async (kind) => {
        const controller = window.smokeTerminal;
        const terminal = controller.terminal;
        const encoder = new TextEncoder();
        const canvas = document.querySelector<HTMLCanvasElement>("#terminal canvas")!;
        const context = canvas.getContext("2d")!;
        const lines = {
          plain: "The quick brown fox jumps over the lazy dog 0123456789",
          unicode: "Unicode: café Ελληνικά 日本語 中文 한글 🦀",
          escapes: "\x1b[31mred\x1b[0m \x1b[1;4mstyled\x1b[0m\x1b[10Gcolumn\x1b[K",
        };
        const visible = {
          plain: "The quick brown fox",
          unicode: "café 日本語 中文 한글 🦀",
          escapes: "styled red",
        };
        const expectedLine = {
          plain: lines.plain,
          unicode: lines.unicode,
          escapes: "red stylecolumn",
        };
        const samples: Array<{ bytes: number; writeCallMs: number; writeToCanvasMs: number }> = [];
        const browserPerformance = performance as Performance & {
          memory?: { usedJSHeapSize: number };
        };
        const heap = () => browserPerformance.memory?.usedJSHeapSize ?? null;
        let sampledPeakJsHeapBytes = heap();
        let maxBufferLines = 0;
        const expectedLines = ["LIBTERMINAL_SMOKE_OK"];
        controller.write(encoder.encode("\x1b[?25l"));
        // The first batch warms up parsing, fonts, and rendering; the next 32 are measured.
        for (let batch = 0; batch <= 32; batch++) {
          const red = batch % 2 === 0 ? 32 : 96;
          const marker = `BATCH_${batch}_${visible[kind]}`;
          const batchLines = Array.from({ length: 512 }, (_, line) => {
            const suffix = ` #${batch}:${line}`;
            expectedLines.push(expectedLine[kind] + suffix);
            return lines[kind] + suffix + "\r\n";
          });
          expectedLines.push(marker);
          if (expectedLines.length > 4_096) {
            expectedLines.splice(0, expectedLines.length - 4_096);
          }
          const bytes = encoder.encode(
            "\r\n" + batchLines.join("") + `\x1b[48;2;${red};32;48m${marker}\x1b[K\x1b[0m`,
          );
          const started = performance.now();
          controller.write(bytes);
          const writeCallMs = performance.now() - started;
          // Observe a changing background in the last row, not merely an animation-frame callback.
          for (;;) {
            await new Promise<void>((resolve) => requestAnimationFrame(() => resolve()));
            const pixel = context.getImageData(2, canvas.height - 2, 1, 1).data;
            if (pixel[0] === red && pixel[1] === 32 && pixel[2] === 48) {
              break;
            }
            if (performance.now() - started > 5_000) {
              throw new Error("output was not rendered");
            }
          }
          const writeToCanvasMs = performance.now() - started;
          const buffer = terminal.buffer.active;
          if (buffer.length < Math.min(terminal.rows + 100, expectedLines.length)) {
            throw new Error(`missing retained ${kind} output in batch ${batch}`);
          }
          if (buffer.length >= 4_096) {
            throw new Error("scrollback exceeded the fixed-workload budget");
          }
          for (let row = 0; row < buffer.length; row++) {
            const expected = expectedLines[expectedLines.length - buffer.length + row];
            if (buffer.getLine(row)?.translateToString(true) !== expected) {
              throw new Error(`lost or corrupted ${kind} output in batch ${batch}, row ${row}`);
            }
          }
          maxBufferLines = Math.max(maxBufferLines, buffer.length);
          const usedHeap = heap();
          if (usedHeap !== null) {
            sampledPeakJsHeapBytes = Math.max(sampledPeakJsHeapBytes ?? 0, usedHeap);
          }
          if (batch > 0) {
            samples.push({ bytes: bytes.byteLength, writeCallMs, writeToCanvasMs });
          }
        }
        return {
          runtimeLoadMs: window.smokeRuntimeMs,
          startupMs: window.smokeStartupMs,
          devicePixelRatio,
          columns: terminal.cols,
          rows: terminal.rows,
          scrollback: terminal.options.scrollback,
          maxBufferLines,
          sampledPeakJsHeapBytes,
          samples,
        };
      }, workload);
      expect(errors).toEqual([]);
      // The pinned WASM retains history in chunks; 100 is not an exact line cap.
      // A generous budget still detects retaining the entire 16,896-line workload.
      expect(measurements.maxBufferLines).toBeLessThan(4_096);
      const totalBytes = measurements.samples.reduce((sum, sample) => sum + sample.bytes, 0);
      const totalWriteMs = measurements.samples.reduce(
        (sum, sample) => sum + sample.writeCallMs,
        0,
      );
      const frameTimes = measurements.samples
        .map((sample) => sample.writeToCanvasMs)
        .toSorted((a, b) => a - b);
      const pkg = JSON.parse(await readFile("package.json", "utf8"));
      const baseline = {
        schemaVersion: 1,
        wrapper: pkg.peerDependencies["ghostty-web"],
        assets,
        workload,
        browser: browser.version(),
        platform: process.platform,
        arch: process.arch,
        viewport: page.viewportSize(),
        wasmBytes: (await stat(new URL(import.meta.resolve("ghostty-web/ghostty-vt.wasm")))).size,
        workerAssetModuleBytes: (await stat("dist/worker-assets.js")).size,
        ...measurements,
        totalBytes,
        writeCallMiBPerSecond:
          totalWriteMs > 0 ? totalBytes / 2 ** 20 / (totalWriteMs / 1000) : null,
        medianWriteToCanvasMs: frameTimes[Math.floor(frameTimes.length / 2)],
        p95WriteToCanvasMs: frameTimes[Math.ceil(frameTimes.length * 0.95) - 1],
      };
      const baselinePath = testInfo.outputPath("ghostty-baseline.json");
      await writeFile(baselinePath, JSON.stringify(baseline, null, 2) + "\n");
      await testInfo.attach("ghostty-baseline", {
        path: baselinePath,
        contentType: "application/json",
      });
      console.log(JSON.stringify({ ghosttyBaseline: { ...baseline, samples: undefined } }));
      await page.evaluate(() => window.smokeTerminal.dispose());
      await expect(page.locator("#terminal canvas")).toHaveCount(0);
    });
  }
}

import { expect, test } from "@playwright/test";

test("xterm consumes ordered ANSI and UTF-8 output without Ghostty", async ({ page }) => {
  const requests: string[] = [];
  page.on("request", (request) => requests.push(request.url()));
  await page.goto("/xterm");
  const result = await page.evaluate(async () => {
    const exampleUrl = "/xterm-example.js";
    const { mountXterm } = (await import(exampleUrl)) as typeof import("../../examples/xterm.js");
    const bytes = new TextEncoder().encode("\x1b[32mcafé 日本語\x1b[0m");
    const abortable = {
      async *[Symbol.asyncIterator]() {
        yield bytes.subarray(0, 7);
        yield bytes.subarray(7);
      },
    };
    const mounted = mountXterm(document.body, abortable);
    await mounted.done;
    await new Promise<void>((resolve) => mounted.terminal.write("", resolve));
    const text = mounted.terminal.buffer.active.getLine(0)?.translateToString(true);
    mounted.dispose();
    let returned = false;
    const pending = mountXterm(document.body, {
      [Symbol.asyncIterator]: () => ({
        next: () => new Promise<IteratorResult<Uint8Array>>(() => {}),
        return: async () => {
          returned = true;
          return { done: true, value: undefined };
        },
      }),
    });
    pending.dispose();
    await pending.done;
    return { text, returned, terminals: document.querySelectorAll(".xterm").length };
  });
  expect(result).toEqual({ text: "café 日本語", returned: true, terminals: 0 });
  expect(requests.some((url) => /ghostty|\.wasm/.test(url))).toBe(false);
});

name: Release

on:
  push:
    tags:
      - "v*.*.*"
  workflow_dispatch:
    inputs:
      dry_run:
        description: Validate the release without publishing
        type: boolean
        required: true
        default: true
      version:
        description: Current package version to validate
        type: string
        required: true

permissions:
  contents: read

concurrency:
  group: release-${{ github.ref }}
  cancel-in-progress: false

env:
  NODE_VERSION: 24.22.1

jobs:
  publish:
    name: Validate or publish @openclaw/libterminal
    if: (github.event_name == 'push' && github.ref_protected) || (github.event_name == 'workflow_dispatch' && github.ref == 'refs/heads/main' && inputs.dry_run)
    runs-on: ubuntu-latest
    timeout-minutes: 20
    permissions:
      contents: read
      id-token: write
    steps:
      - name: Check out
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0

      - name: Set up pnpm
        uses: pnpm/action-setup@73e46992e05b19abd31f2f3c20e0e7370d762115 # v6.1.1
        with:
          version: 11.28.6
          run_install: false

      - name: Set up Node
        uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: ${{ env.NODE_VERSION }}
          cache: pnpm
          cache-dependency-path: pnpm-lock.yaml

      - name: Install dependencies
        run: pnpm install --frozen-lockfile

      - name: Validate package metadata
        run: |
          node <<'NODE'
          const { readFileSync } = require("node:fs");

          const pkg = JSON.parse(readFileSync("package.json", "utf8"));
          const expectedName = "@openclaw/libterminal";
          const expectedAuthor = "OpenClaw Team <dev@openclaw.ai>";
          const expectedRepo = "https://github.com/openclaw/libterminal";
          const repository = typeof pkg.repository === "string"
            ? pkg.repository
            : pkg.repository?.url;
          const normalize = (value) =>
            String(value ?? "")
              .trim()
              .replace(/^git\+/, "")
              .replace(/\.git$/i, "")
              .replace(/\/+$/, "");

          const errors = [];
          if (pkg.name !== expectedName) {
            errors.push(`package name must be ${expectedName}; found ${pkg.name ?? "<missing>"}`);
          }
          if (pkg.author !== expectedAuthor) {
            errors.push(`package author must be ${expectedAuthor}; found ${pkg.author ?? "<missing>"}`);
          }
          if (normalize(repository) !== expectedRepo) {
            errors.push(`repository URL must be ${expectedRepo}; found ${normalize(repository) || "<missing>"}`);
          }
          if (pkg.private === true) {
            errors.push("package must not be private");
          }
          if (errors.length > 0) {
            for (const error of errors) console.error(error);
            process.exit(1);
          }
          NODE

      - name: Validate release tag
        if: github.event_name == 'push'
        env:
          RELEASE_SHA: ${{ github.sha }}
          RELEASE_TAG: ${{ github.ref_name }}
        run: |
          set -euo pipefail
          git fetch --no-tags origin main

          node <<'NODE'
          const { execFileSync } = require("node:child_process");
          const { readFileSync } = require("node:fs");

          const pkg = JSON.parse(readFileSync("package.json", "utf8"));
          const releaseTag = process.env.RELEASE_TAG ?? "";
          const releaseSha = process.env.RELEASE_SHA ?? "";
          const expectedTag = `v${pkg.version}`;

          if (!/^v\d+\.\d+\.\d+$/.test(releaseTag)) {
            throw new Error(`release tag must match vX.Y.Z; received ${releaseTag || "<missing>"}`);
          }
          if (releaseTag !== expectedTag) {
            throw new Error(`release tag ${releaseTag} does not match package version ${pkg.version}`);
          }
          execFileSync("git", ["merge-base", "--is-ancestor", releaseSha, "origin/main"]);
          NODE

      - name: Validate dry-run version
        if: github.event_name == 'workflow_dispatch'
        env:
          EXPECTED_VERSION: ${{ inputs.version }}
        run: |
          node <<'NODE'
          const { readFileSync } = require("node:fs");
          const pkg = JSON.parse(readFileSync("package.json", "utf8"));
          if (process.env.EXPECTED_VERSION !== pkg.version) {
            throw new Error(`dry-run version must match package version ${pkg.version}`);
          }
          NODE

      - name: Ensure version is unpublished
        if: github.event_name == 'push'
        run: |
          set -euo pipefail
          package_name="$(node -p "require('./package.json').name")"
          package_version="$(node -p "require('./package.json').version")"
          set +e
          output="$(npm view "${package_name}@${package_version}" version 2>&1)"
          status=$?
          set -e
          if [ "${status}" -eq 0 ]; then
            echo "${package_name}@${package_version} is already published."
            exit 1
          fi
          if ! printf '%s\n' "${output}" | grep -q "E404"; then
            printf '%s\n' "${output}" >&2
            exit "${status}"
          fi

      - name: Install Chromium
        run: pnpm exec playwright install --with-deps chromium

      - name: Release check
        run: pnpm run check:release

      - name: Publish with npm trusted publishing
        if: github.event_name == 'push'
        run: npm publish --access public --provenance

name: Composed stream measurement

on:
  workflow_dispatch:

permissions:
  contents: read

concurrency:
  group: stream-measurement-${{ github.ref }}
  cancel-in-progress: false

jobs:
  measure:
    name: Full composed stream measurement
    runs-on: ubuntu-24.04
    timeout-minutes: 40
    defaults:
      run:
        shell: bash
    steps:
      - name: Check out exact source
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ github.sha }}
          persist-credentials: false

      - name: Set up pnpm
        uses: pnpm/action-setup@73e46992e05b19abd31f2f3c20e0e7370d762115 # v6.1.1
        with:
          version: 11.28.6
          run_install: false

      - name: Set up Node
        uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: 24.22.1

      - name: Verify toolchain and install dependencies
        run: |
          test "$(node --version)" = v24.22.1
          test "$(pnpm --version)" = 11.28.6
          pnpm install --frozen-lockfile

      - name: Check
        timeout-minutes: 20
        run: pnpm check

      - name: Measure all 24 cells
        id: measure
        timeout-minutes: 14
        run: node scripts/benchmark-stream.mjs > "$RUNNER_TEMP/stream-benchmark.json"

      - name: Validate report and source identity
        id: report
        if: ${{ always() && steps.measure.outcome != 'skipped' }}
        run: |
          node --input-type=module <<'NODE'
          import assert from "node:assert/strict";
          import { createHash } from "node:crypto";
          import { appendFileSync, readFileSync, statSync } from "node:fs";
          import { join } from "node:path";

          const path = join(process.env.RUNNER_TEMP, "stream-benchmark.json");
          assert.ok(statSync(path).size <= 2 * 1024 * 1024, "report exceeds 2 MiB");
          const report = JSON.parse(readFileSync(path, "utf8"));
          // Retain bounded JSON even when sample validity or identity checks fail.
          appendFileSync(process.env.GITHUB_OUTPUT, "bounded=true\n");
          assert.equal(report.schema, 1);
          assert.equal(report.cancelled, false);
          assert.equal(report.plannedSamples, 24);
          assert.equal(report.validSamples, 24);
          assert.equal(report.invalidSamples, 0);
          assert.equal(report.cells.length, 24);
          const harnessSha256 = createHash("sha256")
            .update(readFileSync("scripts/benchmark-stream.mjs"))
            .digest("hex");
          const scenarios = ["live", "replay", "drop-oldest", "disconnect"];
          const build = report.cells[0].measurement.provenance;
          assert.match(build.buildSha256, /^[a-f0-9]{64}$/);
          assert.ok(build.buildFiles.includes("stream.js"));
          for (const [order, cell] of report.cells.entries()) {
            const repetition = Math.floor(order / 8);
            const arms = repetition % 2 === 0 ? ["direct", "batched"] : ["batched", "direct"];
            assert.equal(cell.order, order);
            assert.equal(cell.repetition, repetition);
            assert.deepEqual(cell.workload, {
              scenario: scenarios[Math.floor((order % 8) / 2)],
              arm: arms[order % 2],
              rounds: 64,
              chunkBytes: 1024,
            });
            assert.deepEqual(cell.source, { sourceCommit: process.env.GITHUB_SHA, sourceDirty: false });
            assert.equal(cell.outcome, "success");
            assert.deepEqual(cell.exit, { code: 0, signal: null });
            for (const key of ["valid", "childReaped", "parityValid", "cleanupValid", "resourceAccountingValid"]) {
              assert.equal(cell[key], true, `cell ${order}: ${key}`);
            }
            const provenance = cell.measurement.provenance;
            assert.equal(provenance.node, "v24.22.1");
            assert.equal(provenance.platform, "linux");
            assert.equal(provenance.arch, "x64");
            assert.equal(provenance.packageManager, "pnpm@11.28.6");
            assert.equal(provenance.harnessSha256, harnessSha256);
            assert.equal(provenance.buildSha256, build.buildSha256);
            assert.deepEqual(provenance.buildFiles, build.buildFiles);
          }
          console.log("Validated 24 full cells with matching source, build, and toolchain identities.");
          NODE

      - name: Upload bounded report
        if: ${{ always() && steps.report.outputs.bounded == 'true' }}
        uses: actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9 # v7.0.2
        with:
          name: stream-benchmark-${{ github.sha }}-${{ github.run_id }}-${{ github.run_attempt }}
          path: ${{ runner.temp }}/stream-benchmark.json
          if-no-files-found: error
          retention-days: 7

name: ClawSweeper Dispatch

on:
  issues:
    types: [opened, reopened, edited, labeled, unlabeled]
  issue_comment:
    types: [created, edited]
  pull_request_target: # zizmor: ignore[dangerous-triggers] maintainer-owned external dispatch; no checkout or untrusted PR code execution
    types: [opened, reopened, synchronize, ready_for_review, edited, labeled, unlabeled]

permissions:
  contents: read

concurrency:
  group: clawsweeper-dispatch-${{ github.repository }}-${{ github.event_name }}-${{ github.event.comment.id || github.event.issue.number || github.event.pull_request.number || github.run_id }}-${{ endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled') && github.actor || 'dispatchable' }}
  cancel-in-progress: ${{ github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review' }}

jobs:
  dispatch:
    runs-on: ubuntu-latest
    # id-token proves this repository, event, branch, and run to the queue.
    # The job never checks out or executes pull request code.
    permissions:
      contents: read
      id-token: write
    if: ${{ !(endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled')) }}
    env:
      SUPERSEDES_IN_PROGRESS: ${{ (github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review') && 'true' || 'false' }}
    steps:
      - name: Debounce bursty metadata events
        if: ${{ github.event.action == 'labeled' || github.event.action == 'unlabeled' }}
        run: sleep 20

      - name: Require trusted issue command source
        id: trust
        env:
          EVENT_NAME: ${{ github.event_name }}
          EVENT_ACTION: ${{ github.event.action }}
          COMMENT_AUTHOR_ASSOCIATION: ${{ github.event.comment.author_association || '' }}
          ISSUE_AUTHOR_ASSOCIATION: ${{ github.event.issue.author_association || '' }}
          PR_AUTHOR_ASSOCIATION: ${{ github.event.pull_request.author_association || '' }}
        run: |
          case "$EVENT_NAME" in
            issue_comment) author_association="$COMMENT_AUTHOR_ASSOCIATION" ;;
            issues) author_association="$ISSUE_AUTHOR_ASSOCIATION" ;;
            pull_request_target) author_association="$PR_AUTHOR_ASSOCIATION" ;;
            *) author_association="" ;;
          esac
          case "$EVENT_NAME:$EVENT_ACTION:$author_association" in
            pull_request_target:*:*) allowed=true ;;
            issues:labeled:*|issues:unlabeled:*) allowed=true ;;
            issues:*:OWNER|issues:*:MEMBER|issues:*:COLLABORATOR) allowed=true ;;
            issue_comment:*:OWNER|issue_comment:*:MEMBER|issue_comment:*:COLLABORATOR) allowed=true ;;
            *) allowed=false ;;
          esac
          echo "allowed=$allowed" >> "$GITHUB_OUTPUT"
          if [ "$allowed" != "true" ]; then
            echo "::notice::Skipping ClawSweeper dispatch for untrusted $EVENT_NAME author association."
          fi

      - name: Pre-filter ClawSweeper comment
        id: comment_filter
        if: ${{ steps.trust.outputs.allowed == 'true' && github.event_name == 'issue_comment' }}
        env:
          COMMENT_BODY: ${{ github.event.comment.body }}
        run: |
          set -euo pipefail
          if [[ "$COMMENT_BODY" == *"<!-- clawsweeper-maintainer-opt-in:"* ]]; then
            echo "is_command=false" >> "$GITHUB_OUTPUT"
            exit 0
          fi
          if grep -Eiq '(^|[[:space:]])@(clawsweeper|openclaw-clawsweeper)\b(\[bot\])?|(^|[[:space:]])/(clawsweeper|review|re-review|rerun([[:space:]]+|-)?review|status|explain|fix|build|implement|create([[:space:]]+|-)?pr|fix([[:space:]]+|-)?issue|autofix|auto([[:space:]]+|-)?fix|automerge|auto([[:space:]]+|-)?merge|approve|stop|autoclose)\b' <<< "$COMMENT_BODY"; then
            echo "is_command=true" >> "$GITHUB_OUTPUT"
          else
            echo "is_command=false" >> "$GITHUB_OUTPUT"
          fi

      - name: Dispatch exact ClawSweeper review
        if: ${{ steps.trust.outputs.allowed == 'true' && github.event_name != 'issue_comment' }}
        env:
          TARGET_REPO: ${{ github.repository }}
          TARGET_BRANCH: ${{ github.event.repository.default_branch }}
          ITEM_NUMBER: ${{ github.event.issue.number || github.event.pull_request.number }}
          ITEM_KIND: ${{ github.event_name == 'pull_request_target' && 'pull_request' || 'issue' }}
          SOURCE_EVENT: ${{ github.event_name }}
          SOURCE_ACTION: ${{ github.event.action }}
          TARGET_DISPATCH_URL: https://clawsweeper.openclaw.ai/github/target-dispatch
        run: |
          set -euo pipefail
          source_identity_json="$(node <<'NODE'
          const crypto = require("node:crypto");
          const fs = require("node:fs");
          const event = JSON.parse(fs.readFileSync(process.env.GITHUB_EVENT_PATH, "utf8"));
          const pullRequest = event.pull_request && typeof event.pull_request === "object"
            ? event.pull_request
            : {};
          const issue = event.issue && typeof event.issue === "object" ? event.issue : {};
          const source = process.env.ITEM_KIND === "pull_request" ? pullRequest : issue;
          const headSha = String(pullRequest.head?.sha || "").trim().toLowerCase();
          const baseSha = String(pullRequest.base?.sha || "").trim().toLowerCase();
          const updatedAt = String(pullRequest.updated_at || "").trim();
          const queueClaim = {};
          const result = { queue_claim: queueClaim };
          const sourceUpdatedAt = String(source.updated_at || "").trim();
          if (sourceUpdatedAt && Number.isFinite(Date.parse(sourceUpdatedAt))) {
            queueClaim.source_updated_at = sourceUpdatedAt;
          }
          if (
            typeof source.title === "string" &&
            (source.body === null || typeof source.body === "string") &&
            typeof source.locked === "boolean" &&
            Array.isArray(source.labels)
          ) {
            const labels = [
              ...new Set(
                source.labels
                  .map((label) => String(label?.name || "").trim().toLowerCase())
                  .filter((label) => {
                    if (!label) return false;
                    if (label === "proof: override") return true;
                    if (/^(?:status|rating|proof|merge-risk|impact|issue-rating):/.test(label)) return false;
                    if (/^p[0-3]$/.test(label)) return false;
                    if ([
                      "maturity:stable",
                      "feature: ✨ showcase",
                      "good first issue",
                      "mantis: telegram-visible-proof",
                      "proof: telegram-e2e",
                      "triage: needs-real-behavior-proof",
                      "clawsweeper-recovery-stuck",
                      "no-stale",
                      "stale",
                    ].includes(label)) return false;
                    return !label.startsWith("clawsweeper:") || [
                      "clawsweeper:autofix",
                      "clawsweeper:automerge",
                      "clawsweeper:human-review",
                      "clawsweeper:manual-only",
                      "clawsweeper:bulk-filed",
                    ].includes(label);
                  }),
              ),
            ].sort();
            queueClaim.source_content_revision = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 2,
                  title: source.title,
                  body: source.body || "",
                  locked: source.locked,
                  close_guard_labels: labels,
                }),
              )
              .digest("hex");
          }
          if (process.env.ITEM_KIND === "pull_request") {
            if (/^[0-9a-f]{40}$/.test(headSha)) queueClaim.source_head_sha = headSha;
            if (/^[0-9a-f]{40}$/.test(baseSha)) queueClaim.source_base_sha = baseSha;
            if (typeof pullRequest.draft === "boolean") {
              queueClaim.source_is_draft = pullRequest.draft;
            }
          }
          if (
            process.env.ITEM_KIND !== "pull_request" ||
            !/^[0-9a-f]{40}$/.test(headSha) ||
            !updatedAt
          ) {
            process.stdout.write(JSON.stringify(result));
          } else {
            result.ingress_route = "target_dispatcher";
            result.ingress_fingerprint = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 1,
                  target_repo: String(process.env.TARGET_REPO || "").toLowerCase(),
                  item_number: Number(process.env.ITEM_NUMBER),
                  action: String(process.env.SOURCE_ACTION || ""),
                  head_sha: headSha,
                  updated_at: updatedAt,
                  body: typeof pullRequest.body === "string" ? pullRequest.body : "",
                  label: String(event.label?.name || ""),
                }),
              )
              .digest("hex");
            process.stdout.write(JSON.stringify(result));
          }
          NODE
          )"
          client_payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --arg target_branch "$TARGET_BRANCH" \
            --argjson item_number "$ITEM_NUMBER" \
            --arg item_kind "$ITEM_KIND" \
            --arg source_event "$SOURCE_EVENT" \
            --arg source_action "$SOURCE_ACTION" \
            --argjson source_identity "$source_identity_json" \
            --argjson supersedes_in_progress "$SUPERSEDES_IN_PROGRESS" \
            '{target_repo:$target_repo,target_branch:$target_branch,item_number:$item_number,item_kind:$item_kind,source_event:$source_event,source_action:$source_action,supersedes_in_progress:$supersedes_in_progress} + $source_identity')"
          # The App webhook remains an independent delivery route.
          if [ -n "${ACTIONS_ID_TOKEN_REQUEST_URL:-}" ] &&
            [ -n "${ACTIONS_ID_TOKEN_REQUEST_TOKEN:-}" ] &&
            oidc_token="$(curl --fail --silent --show-error --connect-timeout 5 --max-time 15 \
              --header "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
              --get --data-urlencode "audience=$TARGET_DISPATCH_URL" \
              "$ACTIONS_ID_TOKEN_REQUEST_URL" | jq -er '.value | strings | select(length > 0)')" &&
            [ -n "$oidc_token" ]; then
            echo "::add-mask::$oidc_token"
            direct_body="$RUNNER_TEMP/clawsweeper-direct-intake.json"
            if direct_status="$(curl --silent --show-error --connect-timeout 5 --max-time 20 \
              --request POST \
              --header "authorization: Bearer $oidc_token" \
              --header "content-type: application/json" \
              --data "$client_payload" \
              --output "$direct_body" \
              --write-out '%{http_code}' \
              "$TARGET_DISPATCH_URL")" &&
              [[ "$direct_status" == 2[0-9][0-9] ]]; then
              echo "Queued ClawSweeper intake directly: $(jq -c . "$direct_body" 2>/dev/null || echo '{}')"
              exit 0
            fi
            # Only non-transient 4xx is a deliberate refusal; the App webhook covers it.
            # Timeouts, throttling, and verifier/Worker failures must stay re-runnable.
            if [[ "${direct_status:-}" == 4[0-9][0-9] && "$direct_status" != 408 && "$direct_status" != 429 ]]; then
              echo "::warning::ClawSweeper intake declined this event (HTTP $direct_status); the App webhook route still applies."
              exit 0
            fi
            echo "::error::ClawSweeper intake unavailable (HTTP ${direct_status:-none}); re-run this job after the Worker recovers."
          else
            echo "::error::ClawSweeper OIDC token unavailable; the dispatch job needs id-token: write."
          fi
          exit 1
      - name: Dispatch ClawSweeper comment
        if: >-
          ${{
            steps.trust.outputs.allowed == 'true' &&
            github.event_name == 'issue_comment' &&
            steps.comment_filter.outputs.is_command == 'true'
          }}
        env:
          TARGET_REPO: ${{ github.repository }}
          ITEM_NUMBER: ${{ github.event.issue.number }}
          COMMENT_ID: ${{ github.event.comment.id }}
          SOURCE_ACTION: ${{ github.event.action }}
          TARGET_DISPATCH_URL: https://clawsweeper.openclaw.ai/github/target-dispatch
        run: |
          set -euo pipefail
          client_payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --argjson item_number "$ITEM_NUMBER" \
            --argjson comment_id "$COMMENT_ID" \
            --arg source_action "$SOURCE_ACTION" \
            '{target_repo:$target_repo,item_number:$item_number,comment_id:$comment_id,source_event:"issue_comment",source_action:$source_action}')"
          # The App webhook remains an independent delivery route.
          if [ -n "${ACTIONS_ID_TOKEN_REQUEST_URL:-}" ] &&
            [ -n "${ACTIONS_ID_TOKEN_REQUEST_TOKEN:-}" ] &&
            oidc_token="$(curl --fail --silent --show-error --connect-timeout 5 --max-time 15 \
              --header "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
              --get --data-urlencode "audience=$TARGET_DISPATCH_URL" \
              "$ACTIONS_ID_TOKEN_REQUEST_URL" | jq -er '.value | strings | select(length > 0)')" &&
            [ -n "$oidc_token" ]; then
            echo "::add-mask::$oidc_token"
            direct_body="$RUNNER_TEMP/clawsweeper-direct-intake.json"
            if direct_status="$(curl --silent --show-error --connect-timeout 5 --max-time 20 \
              --request POST \
              --header "authorization: Bearer $oidc_token" \
              --header "content-type: application/json" \
              --data "$client_payload" \
              --output "$direct_body" \
              --write-out '%{http_code}' \
              "$TARGET_DISPATCH_URL")" &&
              [[ "$direct_status" == 2[0-9][0-9] ]]; then
              echo "Queued ClawSweeper intake directly: $(jq -c . "$direct_body" 2>/dev/null || echo '{}')"
              exit 0
            fi
            # Only non-transient 4xx is a deliberate refusal; the App webhook covers it.
            # Timeouts, throttling, and verifier/Worker failures must stay re-runnable.
            if [[ "${direct_status:-}" == 4[0-9][0-9] && "$direct_status" != 408 && "$direct_status" != 429 ]]; then
              echo "::warning::ClawSweeper intake declined this event (HTTP $direct_status); the App webhook route still applies."
              exit 0
            fi
            echo "::error::ClawSweeper intake unavailable (HTTP ${direct_status:-none}); re-run this job after the Worker recovers."
          else
            echo "::error::ClawSweeper OIDC token unavailable; the dispatch job needs id-token: write."
          fi
          exit 1

