import { hasArrayBuffer } from "./bytes.js";
import {
  TerminalMessageType,
  encodeTerminalFrame,
  tryDecodeTerminalFrame,
  type TerminalFrame,
  type TerminalFrameLimits,
  type TerminalMessageType as TerminalFrameMessageType,
} from "./protocol.js";
import { safeClose } from "./websocket-close.js";

export type TerminalHubWebSocket = {
  readonly readyState: number;
  binaryType?: string;
  send(data: string | ArrayBuffer | ArrayBufferView | Blob): void;
  close(code?: number, reason?: string): void;
  addEventListener(type: "open", listener: () => void): void;
  addEventListener(type: "message", listener: (event: { data: unknown }) => void): void;
  addEventListener(
    type: "close",
    listener: (event: { code?: number; reason?: string }) => void,
  ): void;
  addEventListener(type: "error", listener: () => void): void;
  removeEventListener(type: "open", listener: () => void): void;
  removeEventListener(type: "message", listener: (event: { data: unknown }) => void): void;
  removeEventListener(
    type: "close",
    listener: (event: { code?: number; reason?: string }) => void,
  ): void;
  removeEventListener(type: "error", listener: () => void): void;
};

export type TerminalHubClientOptions = {
  url: string | (() => string);
  frameLimits?: TerminalFrameLimits;
  reconnectDelayMs?: number;
  shouldReconnect?: () => boolean;
  socketFactory?: (url: string) => TerminalHubWebSocket;
  onOpen?: () => void;
  onFrame?: (frame: TerminalFrame) => void;
  onClose?: (event: { code?: number; reason?: string }) => void;
  onError?: (error?: unknown) => void;
};

const textEncoder = new TextEncoder();
const WEB_SOCKET_CLOSING = 2;
const WEB_SOCKET_OPEN = 1;

export class TerminalHubClient {
  private readonly options: TerminalHubClientOptions;
  private socket: TerminalHubWebSocket | undefined;
  private reconnectTimer: ReturnType<typeof setTimeout> | undefined;
  private closedByCaller = false;

  constructor(options: TerminalHubClientOptions) {
    this.options = options;
  }

  get isOpen(): boolean {
    return this.socket?.readyState === WEB_SOCKET_OPEN;
  }

  connect(): void {
    this.closedByCaller = false;
    if (this.socket && this.socket.readyState < WEB_SOCKET_CLOSING) {
      return;
    }
    this.clearReconnectTimer();
    let socket: TerminalHubWebSocket;
    try {
      socket = (this.options.socketFactory ?? defaultTerminalHubSocketFactory)(this.resolveUrl());
    } catch (error) {
      this.reportError(error);
      this.scheduleReconnect();
      return;
    }
    this.socket = socket;
    let messageQueue = Promise.resolve();
    const enqueueMessage = (task: () => Promise<void>) => {
      messageQueue = messageQueue
        .catch(noop)
        .then(task)
        .catch((error: unknown) => this.reportError(error));
    };
    socket.binaryType = "arraybuffer";
    socket.addEventListener("open", this.handleOpen(socket));
    socket.addEventListener("message", this.handleMessage(socket, enqueueMessage));
    socket.addEventListener("close", this.handleClose(socket));
    socket.addEventListener("error", this.handleError(socket));
  }

  send(params: {
    type: TerminalFrameMessageType;
    sessionId?: string;
    payload?: Uint8Array;
  }): boolean {
    const socket = this.socket;
    if (!socket || socket.readyState !== WEB_SOCKET_OPEN) {
      return false;
    }
    try {
      socket.send(encodeTerminalFrame(params, this.options.frameLimits));
      return true;
    } catch (error) {
      this.reportError(error);
      return false;
    }
  }

  close(code = 1000, reason = "terminal hub closed"): void {
    this.closedByCaller = true;
    this.clearReconnectTimer();
    const socket = this.socket;
    if (!socket || socket.readyState >= WEB_SOCKET_CLOSING) {
      return;
    }
    safeClose(socket, code, reason, (error) => this.reportError(error));
  }

  private handleOpen(socket: TerminalHubWebSocket): () => void {
    return () => {
      if (this.socket !== socket || this.closedByCaller) {
        return;
      }
      this.send({ type: TerminalMessageType.Hello });
      this.notify(() => this.options.onOpen?.());
    };
  }

  private handleMessage(
    socket: TerminalHubWebSocket,
    enqueueMessage: (task: () => Promise<void>) => void,
  ): (event: { data: unknown }) => void {
    return (event) => {
      if (this.socket !== socket || this.closedByCaller) {
        return;
      }
      const bytes = terminalFrameBytes(event.data);
      // Capture mutable bytes now and handle conversion failures while delivery is queued.
      void bytes.catch(noop);
      enqueueMessage(async () => {
        if (this.socket !== socket || this.closedByCaller) {
          return;
        }
        const frame = tryDecodeTerminalFrame(await bytes, this.options.frameLimits);
        if (frame && this.socket === socket && !this.closedByCaller) {
          this.notify(() => this.options.onFrame?.(frame));
        }
      });
    };
  }

  private handleClose(
    socket: TerminalHubWebSocket,
  ): (event: { code?: number; reason?: string }) => void {
    return (event) => {
      if (this.socket !== socket) {
        return;
      }
      this.socket = undefined;
      this.notify(() => this.options.onClose?.(event));
      this.scheduleReconnect();
    };
  }

  private handleError(socket: TerminalHubWebSocket): () => void {
    return () => {
      if (this.socket === socket) {
        this.reportError();
      }
    };
  }

  private resolveUrl(): string {
    return typeof this.options.url === "function" ? this.options.url() : this.options.url;
  }

  private scheduleReconnect(): void {
    if (this.closedByCaller || this.reconnectTimer || !this.shouldReconnect()) {
      return;
    }
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = undefined;
      // The application's need for a connection can change during the delay.
      if (this.shouldReconnect() && !this.closedByCaller) {
        this.connect();
      }
    }, this.options.reconnectDelayMs ?? 1500);
  }

  private shouldReconnect(): boolean {
    try {
      return Boolean(this.options.shouldReconnect?.());
    } catch (error) {
      this.reportError(error);
      return false;
    }
  }

  private clearReconnectTimer(): void {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = undefined;
    }
  }

  private notify(callback: () => void): void {
    try {
      callback();
    } catch (error) {
      this.reportError(error);
    }
  }

  private reportError(error?: unknown): void {
    try {
      this.options.onError?.(error);
    } catch {
      // Product error callbacks must not interrupt terminal transport cleanup.
    }
  }
}

function defaultTerminalHubSocketFactory(url: string): TerminalHubWebSocket {
  return new WebSocket(url);
}

async function terminalFrameBytes(data: unknown): Promise<Uint8Array> {
  if (data instanceof ArrayBuffer) {
    return new Uint8Array(new Uint8Array(data));
  }
  if (ArrayBuffer.isView(data)) {
    return new Uint8Array(new Uint8Array(data.buffer, data.byteOffset, data.byteLength));
  }
  if (hasArrayBuffer(data)) {
    return new Uint8Array(new Uint8Array(await data.arrayBuffer()));
  }
  return textEncoder.encode(String(data));
}

function noop(): void {}

export type TerminalDefaultColors = Readonly<{
  foreground: string;
  background: string;
  cursor: string;
}>;

export type TerminalDefaultColorQueryResponder = {
  /** Observes live terminal output and replies to complete default-color queries. */
  observe(data: string): void;
  /** Resets parser state from an authoritative replay without answering historical queries. */
  primeFromReplay(data: string): void;
};

export type TerminalDefaultColorQueryResponderOptions = {
  getColors: () => TerminalDefaultColors;
  reply: (data: string) => void;
};

type DynamicColorName = keyof TerminalDefaultColors;

const ESC = "\u001b";
const BEL = "\u0007";
const CAN = "\u0018";
const SUB = "\u001a";
const ST = `${ESC}\\`;
const MAX_PENDING_COLOR_SEQUENCE_CHARS = 1024;

const DYNAMIC_COLOR_SLOTS = [
  { color: "foreground", slot: 10 },
  { color: "background", slot: 11 },
  { color: "cursor", slot: 12 },
] as const satisfies ReadonlyArray<{ color: DynamicColorName; slot: number }>;
const DYNAMIC_COLOR_HEADERS = DYNAMIC_COLOR_SLOTS.map(({ slot }) => ({
  sequence: `${ESC}]${slot};`,
  slot,
}));

type OscTerminator = typeof BEL | typeof ST;
type OscBoundary =
  | { kind: "cancel"; index: number }
  | { kind: "restart"; index: number }
  | { kind: "terminator"; index: number; terminator: OscTerminator };

function findOscBoundary(data: string, start: number): OscBoundary | null {
  for (let index = start; index < data.length; index += 1) {
    if (data[index] === BEL) {
      return { kind: "terminator", index, terminator: BEL };
    }
    if (data[index] === CAN || data[index] === SUB) {
      return { kind: "cancel", index };
    }
    if (data[index] === ESC && data[index + 1] === "\\") {
      return { kind: "terminator", index, terminator: ST };
    }
    if (data[index] === ESC && data[index + 1] === "]") {
      return { kind: "restart", index };
    }
  }
  return null;
}

function formatOscColor(slot: number, color: string, terminator: OscTerminator): string | null {
  const match = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/iu.exec(color);
  if (!match) {
    return null;
  }
  const [, red, green, blue] = match;
  return `${ESC}]${slot};rgb:${red}${red}/${green}${green}/${blue}${blue}${terminator}`;
}

/**
 * Answers streamed OSC 10-12 dynamic-color queries for browser terminals whose
 * emulator does not emit those replies. Color values must use `#rrggbb` syntax.
 */
export function createTerminalDefaultColorQueryResponder(
  options: TerminalDefaultColorQueryResponderOptions,
): TerminalDefaultColorQueryResponder {
  let pending = "";
  let flushingReplies = false;
  const replies: string[] = [];

  const flushReplies = (): void => {
    if (flushingReplies) {
      return;
    }
    flushingReplies = true;
    let sent = 0;
    try {
      while (sent < replies.length) {
        options.reply(replies[sent]);
        sent += 1;
      }
    } finally {
      replies.splice(0, sent);
      flushingReplies = false;
    }
  };

  const process = (data: string, shouldReply: boolean): void => {
    pending += data;
    while (pending.length > 0) {
      const queryStart = pending.indexOf(`${ESC}]`);
      if (queryStart === -1) {
        pending = pending.endsWith(ESC) ? ESC : "";
        break;
      }
      if (queryStart > 0) {
        pending = pending.slice(queryStart);
      }

      const header = DYNAMIC_COLOR_HEADERS.find(({ sequence }) => pending.startsWith(sequence));
      if (!header) {
        if (DYNAMIC_COLOR_HEADERS.some(({ sequence }) => sequence.startsWith(pending))) {
          break;
        }
        pending = pending.slice(1);
        continue;
      }

      const boundary = findOscBoundary(pending, header.sequence.length);
      if (!boundary) {
        if (pending.length <= MAX_PENDING_COLOR_SEQUENCE_CHARS) {
          break;
        }
        pending = pending.slice(1);
        continue;
      }
      if (boundary.kind === "restart") {
        pending = pending.slice(boundary.index);
        continue;
      }
      if (boundary.kind === "cancel") {
        pending = pending.slice(boundary.index + 1);
        continue;
      }

      if (shouldReply) {
        const colors = options.getColors();
        let slot = header.slot;
        const payload = pending.slice(header.sequence.length, boundary.index);
        for (const value of payload.split(";")) {
          if (value) {
            const target = DYNAMIC_COLOR_SLOTS.find((entry) => entry.slot === slot);
            if (value === "?" && target) {
              const response = formatOscColor(slot, colors[target.color], boundary.terminator);
              if (response) {
                replies.push(response);
              }
            }
          }
          slot += 1;
        }
      }
      pending = pending.slice(boundary.index + boundary.terminator.length);
    }
    if (shouldReply) {
      flushReplies();
    }
  };

  return {
    observe(data: string): void {
      process(data, true);
    },
    primeFromReplay(data: string): void {
      pending = "";
      process(data, false);
    },
  };
}

