export type FakeTerminalDuplex = TerminalDuplex & {
  readonly writes: Uint8Array[];
  readonly sizes: TerminalSize[];
  readonly closeReasons: Array<string | undefined>;
  emitOutput(bytes: Uint8Array): void;
  endOutput(): void;
};

export function createFakeTerminalDuplex(): FakeTerminalDuplex {
  const output = new AsyncByteQueue(Number.POSITIVE_INFINITY);
  const writes: Uint8Array[] = [];
  const sizes: TerminalSize[] = [];
  const closeReasons: Array<string | undefined> = [];
  return {
    output,
    writes,
    sizes,
    closeReasons,
    write: async (bytes) => {
      writes.push(new Uint8Array(bytes));
    },
    resize: async (size) => {
      sizes.push({ ...size });
    },
    close: async (reason) => {
      closeReasons.push(reason);
      output.close();
    },
    emitOutput: (bytes) => {
      output.enqueue(bytes, "drop-oldest");
    },
    endOutput: () => output.close(),
  };
}

type FakeWebSocketListeners = {
  message: (event: WebSocketMessageEventLike) => void;
  close: (event: WebSocketCloseEventLike) => void;
  error: () => void;
};

export class FakeWebSocket implements WebSocketLike {
  readyState = WEB_SOCKET_OPEN;
  readonly sent: WebSocketPayload[] = [];
  closed?: { code?: number; reason?: string };
  private readonly listeners: {
    [Type in keyof FakeWebSocketListeners]: Set<FakeWebSocketListeners[Type]>;
  } = { message: new Set(), close: new Set(), error: new Set() };

  send(data: WebSocketPayload): void {
    this.sent.push(data);
  }

  close(code?: number, reason?: string): void {
    this.closed = { code, reason };
    this.readyState = 3;
  }

  addEventListener<Type extends keyof FakeWebSocketListeners>(
    type: Type,
    listener: FakeWebSocketListeners[Type],
  ): void {
    this.listeners[type].add(listener);
  }

  removeEventListener<Type extends keyof FakeWebSocketListeners>(
    type: Type,
    listener: FakeWebSocketListeners[Type],
  ): void {
    this.listeners[type].delete(listener);
  }

  receive(data: unknown): void {
    for (const listener of this.listeners.message) {
      listener({ data });
    }
  }

  emitClose(code = 1000, reason = ""): void {
    this.readyState = 3;
    for (const listener of this.listeners.close) {
      listener({ code, reason });
    }
  }

  emitError(): void {
    for (const listener of this.listeners.error) {
      listener();
    }
  }
}

export class ManualClock {
  private currentTime = 0;
  private nextId = 1;
  private readonly tasks = new Map<number, { at: number; callback: () => void }>();

  now(): number {
    return this.currentTime;
  }

  setTimeout(callback: () => void, delayMs: number): number {
    const id = this.nextId++;
    this.tasks.set(id, { at: this.currentTime + Math.max(0, delayMs), callback });
    return id;
  }

  clearTimeout(id: number): void {
    this.tasks.delete(id);
  }

  advanceBy(durationMs: number): void {
    if (!Number.isFinite(durationMs) || durationMs < 0) {
      throw new RangeError("durationMs must be a non-negative finite number");
    }
    const target = this.currentTime + durationMs;
    for (;;) {
      const next = this.nextTask(target);
      if (!next) {
        break;
      }
      this.currentTime = next.at;
      this.tasks.delete(next.id);
      next.callback();
    }
    this.currentTime = target;
  }

  private nextTask(target: number): { id: number; at: number; callback: () => void } | undefined {
    let selected: { id: number; at: number; callback: () => void } | undefined;
    for (const [id, task] of this.tasks) {
      if (task.at > target || (selected && selected.at <= task.at)) {
        continue;
      }
      selected = { id, ...task };
    }
    return selected;
  }
}

export function terminalBytes(value: string): Uint8Array {
  return new TextEncoder().encode(value);
}

export function terminalText(chunks: Iterable<Uint8Array>): string {
  return new TextDecoder().decode(concatenateBytes([...chunks]));
}

export async function collectTerminalOutput(
  output: AsyncIterable<Uint8Array>,
  limit = Number.POSITIVE_INFINITY,
): Promise<Uint8Array[]> {
  const chunks: Uint8Array[] = [];
  for await (const chunk of output) {
    chunks.push(new Uint8Array(chunk));
    if (chunks.length >= limit) {
      break;
    }
  }
  return chunks;
}

import { describe, expect, it, vi } from "vitest";
import { cleanReason, safeClose } from "../src/websocket-close.js";

describe("WebSocket close reason limits", () => {
  it.each([
    ["ASCII", "a".repeat(124), "a".repeat(123)],
    ["two-byte", "é".repeat(62), "é".repeat(61)],
    ["three-byte", "界".repeat(42), "界".repeat(41)],
    ["four-byte", "🦊".repeat(31), "🦊".repeat(30)],
    ["exact boundary", "é".repeat(60) + "界x", "é".repeat(60) + "界"],
    ["surrogate boundary", "a".repeat(120) + "\ud800x", "a".repeat(120) + "\ud800"],
  ])("keeps the complete UTF-8 prefix for %s", (_name, source, expected) => {
    expect(cleanReason(source)).toBe(expected);
    const close = vi.fn();
    safeClose({ close }, 1000, source);
    expect(close).toHaveBeenCalledWith(1000, expected);
    expect(new TextEncoder().encode(expected).byteLength).toBeLessThanOrEqual(123);
  });
});

import { once } from "node:events";
import type { AddressInfo } from "node:net";
import { describe, expect, it, vi } from "vitest";
import { WebSocketServer } from "ws";
import { TerminalHubClient } from "../src/browser.js";
import { encodeTerminalFrame, TerminalMessageType } from "../src/protocol.js";

describe("TerminalHubClient native WebSocket teardown", () => {
  it("drops queued frames as soon as the caller closes", async () => {
    const server = new WebSocketServer({ host: "127.0.0.1", port: 0 });
    let client: TerminalHubClient | undefined;
    try {
      await once(server, "listening");
      const onFrame = vi.fn();
      let markClosed!: () => void;
      const closed = new Promise<void>((resolve) => {
        markClosed = resolve;
      });
      client = new TerminalHubClient({
        url: `ws://127.0.0.1:${(server.address() as AddressInfo).port}`,
        socketFactory: (url) => {
          const socket = new WebSocket(url);
          socket.addEventListener("message", () => queueMicrotask(() => client?.close()));
          return socket;
        },
        onFrame,
        onClose: markClosed,
      });
      const connected = once(server, "connection");
      client.connect();
      const [peer] = await connected;
      peer.send(
        encodeTerminalFrame({ type: TerminalMessageType.Output, payload: new Uint8Array([65]) }),
      );
      await closed;
      expect(onFrame).not.toHaveBeenCalled();
    } finally {
      client?.close();
      for (const peer of server.clients) {
        peer.terminate();
      }
      await new Promise<void>((resolve) => server.close(() => resolve()));
    }
  });

  it.each([
    {
      name: "reserved code",
      code: 1006,
      reason: "done",
      expectedCode: 1000,
      expectedReason: "done",
    },
    {
      name: "out-of-range code",
      code: 999,
      reason: "done",
      expectedCode: 1000,
      expectedReason: "done",
    },
    {
      name: "browser-disallowed code",
      code: 1001,
      reason: "done",
      expectedCode: 1000,
      expectedReason: "done",
    },
    {
      name: "oversized ASCII",
      code: 1000,
      reason: "x".repeat(200),
      expectedCode: 1000,
      expectedReason: "x".repeat(123),
    },
    {
      name: "fractional code",
      code: 4001.5,
      reason: "done",
      expectedCode: 1000,
      expectedReason: "done",
    },
    {
      name: "oversized Unicode",
      code: 1000,
      reason: "🦞".repeat(40),
      expectedCode: 1000,
      expectedReason: "🦞".repeat(30),
    },
    {
      name: "valid application code and whitespace",
      code: 4001,
      reason: " keep spaces ",
      expectedCode: 4001,
      expectedReason: " keep spaces ",
    },
    {
      name: "default arguments",
      code: undefined,
      reason: undefined,
      expectedCode: 1000,
      expectedReason: "terminal hub closed",
    },
  ])("closes the real peer for $name", async ({ code, reason, expectedCode, expectedReason }) => {
    const server = new WebSocketServer({ host: "127.0.0.1", port: 0 });
    try {
      await once(server, "listening");
      const errors: unknown[] = [];
      const closes: Array<{ code?: number; reason?: string }> = [];
      let markOpen: (() => void) | undefined;
      const opened = new Promise<void>((resolve) => {
        markOpen = resolve;
      });
      const client = new TerminalHubClient({
        url: `ws://127.0.0.1:${(server.address() as AddressInfo).port}`,
        onOpen: () => markOpen?.(),
        onClose: (event) => closes.push(event),
        onError: (error) => errors.push(error),
      });
      const connected = once(server, "connection");
      client.connect();
      const [peer] = await connected;
      await opened;
      let peerClose: { code: number; reason: string } | undefined;
      peer.once("close", (closeCode: number, closeReason: Buffer) => {
        peerClose = { code: closeCode, reason: closeReason.toString() };
      });

      client.close(code, reason);

      await vi.waitFor(() => {
        expect(peerClose).toEqual({ code: expectedCode, reason: expectedReason });
        expect(closes).toHaveLength(1);
      });
      expect(closes[0]).toMatchObject({ code: expectedCode, reason: expectedReason });
      expect(client.isOpen).toBe(false);
      expect(server.clients.size).toBe(0);
      expect(errors).toEqual([]);
    } finally {
      for (const peer of server.clients) {
        peer.terminate();
      }
      await new Promise<void>((resolve) => server.close(() => resolve()));
    }
  });
});

import { describe, expect, it } from "vitest";
import { GHOSTTY_ASSET_PATHS as nodeAssetPaths, readGhosttyAsset } from "../src/node.js";
import {
  createGhosttyAssetResponse,
  GHOSTTY_ASSET_PATHS,
  readGhosttyWorkerAsset,
} from "../src/worker-assets.js";

describe("Worker Ghostty assets", () => {
  it(
    "embeds byte-exact copies of the pinned Ghostty browser assets",
    { timeout: 10_000 },
    async () => {
      expect(GHOSTTY_ASSET_PATHS).toEqual(nodeAssetPaths);

      for (const pathname of Object.values(GHOSTTY_ASSET_PATHS)) {
        const expected = await readGhosttyAsset(pathname);
        const actual = readGhosttyWorkerAsset(pathname);
        expect(expected, pathname).not.toBeNull();
        expect(actual, pathname).not.toBeNull();
        expect(actual!.contentType).toBe(expected!.contentType);
        expect(Buffer.compare(actual!.body, expected!.body), pathname).toBe(0);
      }
    },
  );

  it("keeps decoded asset bytes isolated from caller mutation", () => {
    const asset = readGhosttyWorkerAsset(GHOSTTY_ASSET_PATHS.wasm);
    expect(asset).not.toBeNull();
    asset!.body.fill(0);
    expect(readGhosttyWorkerAsset(GHOSTTY_ASSET_PATHS.wasm)?.body).not.toEqual(asset!.body);
  });

  it("isolates response bodies from later reads and other response consumers", async () => {
    const pathname = GHOSTTY_ASSET_PATHS.browserExternal;
    const expected = readGhosttyWorkerAsset(pathname)!.body;
    const first = createGhosttyAssetResponse(pathname)!;
    const second = createGhosttyAssetResponse(pathname)!;
    readGhosttyWorkerAsset(pathname)!.body.fill(0);
    const consumed = new Uint8Array(await first.arrayBuffer());
    expect(consumed).toEqual(expected);
    consumed.fill(0);
    expect(new Uint8Array(await second.arrayBuffer())).toEqual(expected);
    const later = createGhosttyAssetResponse(pathname)!;
    expect(new Uint8Array(await later.arrayBuffer())).toEqual(expected);
  });

  it("builds responses with canonical content types and caller policy", async () => {
    const response = createGhosttyAssetResponse(GHOSTTY_ASSET_PATHS.wasm, {
      headers: {
        "cache-control": "no-store",
        "content-type": "text/plain",
        "x-terminal-policy": "viewer",
      },
    });

    expect(response?.status).toBe(200);
    expect(response?.headers.get("content-type")).toBe("application/wasm");
    expect(response?.headers.get("cache-control")).toBe("no-store");
    expect(response?.headers.get("x-terminal-policy")).toBe("viewer");
    expect((await response?.arrayBuffer())?.byteLength).toBeGreaterThan(0);
    expect(createGhosttyAssetResponse("/vendor/missing")).toBeNull();
  });
});

import { execFile } from "node:child_process";
import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { promisify } from "node:util";
import { describe, expect, it } from "vitest";
import { runControls, runScenario, validateWorkload } from "../scripts/benchmark-stream.mjs";
import * as stream from "../src/stream.js";

describe("composed stream measurement contracts", () => {
  for (const scenario of ["live", "replay", "drop-oldest", "disconnect"] as const) {
    it(`${scenario} preserves byte parity through direct and batched publication`, async () => {
      const direct = await runScenario(stream, {
        scenario,
        arm: "direct",
        rounds: 3,
        chunkBytes: 7,
      });
      const batched = await runScenario(stream, {
        scenario,
        arm: "batched",
        rounds: 3,
        chunkBytes: 7,
      });
      expect(direct.fast.bytes).toBe(scenario === "replay" ? 105 : 84);
      expect(direct.fast.sha256).toBe(batched.fast.sha256);
      expect(direct.slow.sha256).toBe(batched.slow.sha256);
      expect(direct.fast.writes).toBeGreaterThan(batched.fast.writes);
      expect(direct.parityValid && batched.parityValid).toBe(true);
      expect(direct.cleanupValid && batched.cleanupValid).toBe(true);
      if (scenario === "drop-oldest") {
        expect(direct.evictedBytes).toBe(28);
        expect(batched.evictedBytes).toBe(28);
        expect(direct.overflowEvents).toBe(4);
        expect(batched.overflowEvents).toBe(1);
      }
      if (scenario === "disconnect") {
        expect(direct.rejectedBytes).toBe(7);
        expect(batched.rejectedBytes).toBe(28);
        expect(direct.notOfferedAfterDisconnectBytes).toBe(21);
        expect(batched.notOfferedAfterDisconnectBytes).toBe(0);
      }
    });
  }

  it("checks copying, reentrant replacement, cancellation, drain and error identity", async () => {
    expect(await runControls(stream)).toEqual({
      reentrancy: true,
      copies: true,
      replacement: true,
      cancellation: true,
      errorIdentity: true,
      stopDrain: true,
      iteratorCleanup: true,
    });
  });

  it("rejects workloads that exceed the finite measurement budget", () => {
    for (const rounds of [0, 2, 1025, Infinity, 3.5]) {
      expect(() =>
        validateWorkload({ scenario: "live", arm: "direct", rounds, chunkBytes: 7 }),
      ).toThrow();
    }
    for (const chunkBytes of [0, 4097, NaN]) {
      expect(() =>
        validateWorkload({ scenario: "live", arm: "direct", rounds: 3, chunkBytes }),
      ).toThrow();
    }
  });
});

type SmokeReport = {
  schema: number;
  cancelled: boolean;
  plannedSamples: number;
  validSamples: number;
  invalidSamples: number;
  cells: Array<{
    valid: boolean;
    outcome: string;
    exit: { code: number | null; signal: string | null };
    childReaped: boolean;
    parityValid: boolean;
    cleanupValid: boolean;
    resourceAccountingValid: boolean;
    wholeChildWallMs: number;
    measurement: {
      provenance: { buildSha256: string; harnessSha256: string; node: string };
      metrics: Record<string, number>;
      result: { fast: { sha256: string }; slow: { sha256: string } };
    };
  }>;
};

// `pnpm check` builds first, so this case must run there. Source-only tests may skip it.
it.skipIf(!existsSync(new URL("../dist/stream.js", import.meta.url)))(
  "built public stream CLI emits eight valid fresh-child smoke cells",
  async () => {
    const { stdout, stderr } = await promisify(execFile)(
      process.execPath,
      [fileURLToPath(new URL("../scripts/benchmark-stream.mjs", import.meta.url)), "--smoke"],
      {
        cwd: new URL("../", import.meta.url),
        timeout: 45_000,
        killSignal: "SIGTERM", // The parent cancels and reaps its current measurement child.
        maxBuffer: 256 * 1024,
      },
    );
    expect(stderr).toBe("");
    const report = JSON.parse(stdout) as SmokeReport;
    expect(report.schema).toBe(1);
    expect(report.cancelled).toBe(false);
    expect(report.plannedSamples).toBe(8);
    expect(report.validSamples).toBe(8);
    expect(report.invalidSamples).toBe(0);
    expect(report.cells).toHaveLength(8);
    for (const cell of report.cells) {
      expect(cell.valid).toBe(true);
      expect(cell.outcome).toBe("success");
      expect(cell.exit).toEqual({ code: 0, signal: null });
      expect(cell.childReaped).toBe(true);
      expect(cell.parityValid).toBe(true);
      expect(cell.cleanupValid).toBe(true);
      expect(cell.resourceAccountingValid).toBe(true);
      expect(cell.measurement.provenance.buildSha256).toMatch(/^[a-f0-9]{64}$/);
      expect(cell.measurement.provenance.harnessSha256).toMatch(/^[a-f0-9]{64}$/);
      expect(cell.measurement.provenance.node).toBe(process.version);
      expect(cell.wholeChildWallMs).toBeGreaterThanOrEqual(
        cell.measurement.metrics.operationWallMs,
      );
      for (const value of Object.values(cell.measurement.metrics)) {
        expect(Number.isFinite(value) && value >= 0).toBe(true);
      }
    }
    for (let index = 0; index < report.cells.length; index += 2) {
      const direct = report.cells[index].measurement.result;
      const batched = report.cells[index + 1].measurement.result;
      expect(direct.fast.sha256).toBe(batched.fast.sha256);
      expect(direct.slow.sha256).toBe(batched.slow.sha256);
    }
  },
  60_000,
);
